  1→package strategy
  2→
  3→import (
  4→	"encoding/json"
  5→	"fmt"
  6→	"sort"
  7→	"strconv"
  8→	"strings"
  9→	"time"
 10→
 11→	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
 12→	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
 13→	"github.com/entireio/cli/cmd/entire/cli/paths"
 14→
 15→	"github.com/go-git/go-git/v5"
 16→)
 17→
 18→// NoDescription is the default description for sessions without one.
 19→const NoDescription = "No description"
 20→
 21→// Session represents a Claude Code session with its checkpoints.
 22→// A session is created when a user runs `claude` and tracks all changes
 23→// made during that interaction.
 24→type Session struct {
 25→	// ID is the unique session identifier (e.g., "2025-12-01-8f76b0e8-b8f1-4a87-9186-848bdd83d62e")
 26→	ID string
 27→
 28→	// Description is a human-readable summary of the session
 29→	// (typically the first prompt or derived from commit messages)
 30→	Description string
 31→
 32→	// Strategy is the name of the strategy that created this session
 33→	Strategy string
 34→
 35→	// StartTime is when the session was started
 36→	StartTime time.Time
 37→
 38→	// Checkpoints is the list of save points within this session
 39→	Checkpoints []Checkpoint
 40→}
 41→
 42→// Checkpoint represents a save point within a session.
 43→// Checkpoints can be either session-level (on Stop) or task-level (on subagent completion).
 44→type Checkpoint struct {
 45→	// CheckpointID is the stable 12-hex-char identifier for this checkpoint.
 46→	// Used to look up metadata at <id[:2]>/<id[2:]>/ on entire/checkpoints/v1 branch.
 47→	CheckpointID id.CheckpointID
 48→
 49→	// Message is the commit message or checkpoint description
 50→	Message string
 51→
 52→	// Timestamp is when this checkpoint was created
 53→	Timestamp time.Time
 54→
 55→	// IsTaskCheckpoint indicates if this is a task checkpoint (vs a session checkpoint)
 56→	IsTaskCheckpoint bool
 57→
 58→	// ToolUseID is the tool use ID for task checkpoints (empty for session checkpoints)
 59→	ToolUseID string
 60→}
 61→
 62→// PromptResponse represents a single user prompt and assistant response pair.
 63→type PromptResponse struct {
 64→	// Prompt is the user's message
 65→	Prompt string
 66→
 67→	// Response is the assistant's response
 68→	Response string
 69→
 70→	// Files is the list of files modified during this prompt/response
 71→	Files []string
 72→}
 73→
 74→// CheckpointDetails contains detailed information extracted from a checkpoint's transcript.
 75→// This is used by the explain command to display checkpoint content.
 76→type CheckpointDetails struct {
 77→	// Interactions contains all prompt/response pairs in this checkpoint.
 78→	// For strategies like auto-commit/commit, this typically has one entry.
 79→	// For strategies like shadow, this may have multiple entries.
 80→	Interactions []PromptResponse
 81→
 82→	// Files is the aggregate list of all files modified in this checkpoint.
 83→	// This is a convenience field that combines files from all interactions.
 84→	Files []string
 85→}
 86→
 87→// ListSessions returns all sessions from the entire/checkpoints/v1 branch,
 88→// plus any additional sessions from strategies implementing SessionSource.
 89→// It automatically discovers all registered strategies and merges their sessions.
 90→func ListSessions() ([]Session, error) {
 91→	repo, err := OpenRepository()
 92→	if err != nil {
 93→		return nil, fmt.Errorf("failed to open git repository: %w", err)
 94→	}
 95→
 96→	// Get checkpoints from the entire/checkpoints/v1 branch
 97→	checkpoints, err := ListCheckpoints()
 98→	if err != nil {
 99→		return nil, fmt.Errorf("failed to list checkpoints: %w", err)
100→	}
101→
102→	// Group checkpoints by session ID
103→	// For multi-session checkpoints, expand SessionIDs array so each session gets the checkpoint
104→	sessionMap := make(map[string]*Session)
105→	for _, cp := range checkpoints {
106→		// Determine which session IDs this checkpoint belongs to
107→		// Multi-session checkpoints have SessionIDs populated; single-session use SessionID
108→		sessionIDs := cp.SessionIDs
109→		if len(sessionIDs) == 0 {
110→			sessionIDs = []string{cp.SessionID}
111→		}
112→
113→		for _, sessionID := range sessionIDs {
114→			if sessionID == "" {
115→				continue
116→			}
117→
118→			if existing, ok := sessionMap[sessionID]; ok {
119→				existing.Checkpoints = append(existing.Checkpoints, Checkpoint{
120→					CheckpointID:     cp.CheckpointID,
121→					Message:          "Checkpoint: " + cp.CheckpointID.String(),
122→					Timestamp:        cp.CreatedAt,
123→					IsTaskCheckpoint: cp.IsTask,
124→					ToolUseID:        cp.ToolUseID,
125→				})
126→			} else {
127→				// Get description from the checkpoint tree
128→				description := getDescriptionForCheckpoint(repo, cp.CheckpointID)
129→
130→				sessionMap[sessionID] = &Session{
131→					ID:          sessionID,
132→					Description: description,
133→					Strategy:    "", // Will be set from metadata if available
134→					StartTime:   cp.CreatedAt,
135→					Checkpoints: []Checkpoint{{
136→						CheckpointID:     cp.CheckpointID,
137→						Message:          "Checkpoint: " + cp.CheckpointID.String(),
138→						Timestamp:        cp.CreatedAt,
139→						IsTaskCheckpoint: cp.IsTask,
140→						ToolUseID:        cp.ToolUseID,
141→					}},
142→				}
143→			}
144→		}
145→	}
146→
147→	// Check all registered strategies for additional sessions
148→	for _, name := range List() {
149→		strat, stratErr := Get(name)
150→		if stratErr != nil {
151→			continue
152→		}
153→		source, ok := strat.(SessionSource)
154→		if !ok {
155→			continue
156→		}
157→		additionalSessions, addErr := source.GetAdditionalSessions()
158→		if addErr != nil {
159→			continue // Skip strategies that fail to provide additional sessions
160→		}
161→		for _, addSession := range additionalSessions {
162→			if addSession == nil {
163→				continue
164→			}
165→			if existing, ok := sessionMap[addSession.ID]; ok {
166→				// Merge checkpoints - deduplicate by CheckpointID
167→				existingCPIDs := make(map[string]bool)
168→				for _, cp := range existing.Checkpoints {
169→					existingCPIDs[cp.CheckpointID.String()] = true
170→				}
171→				for _, cp := range addSession.Checkpoints {
172→					if !existingCPIDs[cp.CheckpointID.String()] {
173→						existing.Checkpoints = append(existing.Checkpoints, cp)
174→					}
175→				}
176→				// Update start time if additional session is older
177→				if addSession.StartTime.Before(existing.StartTime) {
178→					existing.StartTime = addSession.StartTime
179→				}
180→				// Use description from additional source if existing is empty
181→				if existing.Description == "" || existing.Description == NoDescription {
182→					existing.Description = addSession.Description
183→				}
184→			} else {
185→				// New session from additional source
186→				sessionMap[addSession.ID] = addSession
187→			}
188→		}
189→	}
190→
191→	// Convert map to slice
192→	sessions := make([]Session, 0, len(sessionMap))
193→	for _, session := range sessionMap {
194→		// Sort checkpoints within each session by timestamp (most recent first)
195→		sort.Slice(session.Checkpoints, func(i, j int) bool {
196→			return session.Checkpoints[i].Timestamp.After(session.Checkpoints[j].Timestamp)
197→		})
198→		sessions = append(sessions, *session)
199→	}
200→
201→	// Sort sessions by start time (most recent first)
202→	sort.Slice(sessions, func(i, j int) bool {
203→		return sessions[i].StartTime.After(sessions[j].StartTime)
204→	})
205→
206→	return sessions, nil
207→}
208→
209→// GetSession finds a session by ID (supports prefix matching).
210→// Returns ErrNoSession if no matching session is found.
211→func GetSession(sessionID string) (*Session, error) {
212→	sessions, err := ListSessions()
213→	if err != nil {
214→		return nil, err
215→	}
216→	return findSessionByID(sessions, sessionID)
217→}
218→
219→// getDescriptionForCheckpoint reads the description for a checkpoint from the entire/checkpoints/v1 branch.
220→// It reads from the latest session subdirectory in the new storage format.
221→func getDescriptionForCheckpoint(repo *git.Repository, checkpointID id.CheckpointID) string {
222→	tree, err := GetMetadataBranchTree(repo)
223→	if err != nil {
224→		return NoDescription
225→	}
226→
227→	// Get the checkpoint tree
228→	checkpointTree, err := tree.Tree(checkpointID.Path())
229→	if err != nil {
230→		return NoDescription
231→	}
232→
233→	// Read root metadata.json to get session count and sessions map
234→	metadataFile, err := checkpointTree.File(paths.MetadataFileName)
235→	if err != nil {
236→		return NoDescription
237→	}
238→
239→	content, err := metadataFile.Contents()
240→	if err != nil {
241→		return NoDescription
242→	}
243→
244→	var summary checkpoint.CheckpointSummary
245→	if err := json.Unmarshal([]byte(content), &summary); err != nil {
246→		return NoDescription
247→	}
248→
249→	// Find the first session's prompt/context path
250→	// Try to use the latest session for description (0-based indexing)
251→	sessionDir := "0"
252→	if len(summary.Sessions) > 0 {
253→		sessionDir = strconv.Itoa(len(summary.Sessions) - 1) // Use latest session
254→	}
255→
256→	sessionTree, err := checkpointTree.Tree(sessionDir)
257→	if err != nil {
258→		return NoDescription
259→	}
260→
261→	return getSessionDescriptionFromTree(sessionTree, "")
262→}
263→
264→// findSessionByID finds a session by exact ID or prefix match.
265→func findSessionByID(sessions []Session, sessionID string) (*Session, error) {
266→	for _, session := range sessions {
267→		if session.ID == sessionID || strings.HasPrefix(session.ID, sessionID) {
268→			return &session, nil
269→		}
270→	}
271→	return nil, ErrNoSession
272→}
