package dashboard

import (
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

const (
	tabSessions    = 0
	tabCheckpoints = 1
	tabActive      = 2
	tabSettings    = 3
)

var tabNames = []string{"Sessions", "Checkpoints", "Active", "Settings"}

// RewindRequest is returned by Run when the user requests a rewind from the TUI.
type RewindRequest struct {
	PointID string
}

// Model is the root bubbletea model for the dashboard.
type Model struct {
	activeTab    int
	sessions     sessionsModel
	checkpoints  checkpointsModel
	active       activeModel
	settings     settingsModel
	width        int
	height       int
	showHelp     bool
	keys         keyMap
	err          error
	rewindReq    *RewindRequest
	quitting     bool
	dataLoaded   [4]bool // tracks whether each tab's data has loaded
}

func newModel() Model {
	return Model{
		activeTab: tabSessions,
		keys:      newKeyMap(),
		sessions:  newSessionsModel(),
		checkpoints: newCheckpointsModel(),
		active:    newActiveModel(),
		settings:  newSettingsModel(),
	}
}

func (m Model) Init() tea.Cmd {
	return tea.Batch(
		loadSessionsCmd,
		loadCheckpointsCmd,
		loadActiveSessionsCmd,
		loadSettingsCmd,
	)
}

func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		contentHeight := m.contentHeight()
		m.sessions.setSize(m.width, contentHeight)
		m.checkpoints.setSize(m.width, contentHeight)
		m.active.setSize(m.width, contentHeight)
		m.settings.setSize(m.width, contentHeight)
		return m, nil

	case tea.KeyMsg:
		// If a tab is in filter/input mode, delegate to it first
		if m.isTabCapturingInput() {
			return m.updateActiveTab(msg)
		}

		switch {
		case msg.String() == "q" || msg.String() == "ctrl+c":
			m.quitting = true
			return m, tea.Quit
		case msg.String() == "?":
			m.showHelp = !m.showHelp
			return m, nil
		case msg.String() == "tab":
			m.activeTab = (m.activeTab + 1) % len(tabNames)
			return m, nil
		case msg.String() == "shift+tab":
			m.activeTab = (m.activeTab - 1 + len(tabNames)) % len(tabNames)
			return m, nil
		}

		return m.updateActiveTab(msg)

	case sessionsMsg:
		m.dataLoaded[tabSessions] = true
		m.sessions.setSessions(msg.sessions)
		if msg.err != nil {
			m.sessions.err = msg.err
		}
		return m, nil

	case checkpointsMsg:
		m.dataLoaded[tabCheckpoints] = true
		m.checkpoints.setCheckpoints(msg.points)
		if msg.err != nil {
			m.checkpoints.err = msg.err
		}
		return m, nil

	case activeSessionsMsg:
		m.dataLoaded[tabActive] = true
		m.active.setSessions(msg.states)
		if msg.err != nil {
			m.active.err = msg.err
		}
		return m, nil

	case settingsDataMsg:
		m.dataLoaded[tabSettings] = true
		m.settings.setData(msg)
		return m, nil

	case rewindRequestMsg:
		m.rewindReq = &RewindRequest{PointID: msg.pointID}
		m.quitting = true
		return m, tea.Quit
	}

	return m.updateActiveTab(msg)
}

func (m Model) updateActiveTab(msg tea.Msg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.activeTab {
	case tabSessions:
		m.sessions, cmd = m.sessions.update(msg)
	case tabCheckpoints:
		m.checkpoints, cmd = m.checkpoints.update(msg)
	case tabActive:
		m.active, cmd = m.active.update(msg)
	case tabSettings:
		m.settings, cmd = m.settings.update(msg)
	}
	return m, cmd
}

func (m Model) isTabCapturingInput() bool {
	switch m.activeTab {
	case tabSessions:
		return m.sessions.filtering
	case tabCheckpoints:
		return m.checkpoints.filtering || m.checkpoints.confirming
	}
	return false
}

func (m Model) View() string {
	if m.quitting {
		return ""
	}

	var b strings.Builder

	// Tab bar
	b.WriteString(m.renderTabBar())
	b.WriteString("\n")

	// Content
	contentHeight := m.contentHeight()
	content := m.renderActiveTab(contentHeight)
	b.WriteString(content)

	// Help / status bar
	b.WriteString("\n")
	b.WriteString(m.renderStatusBar())

	return b.String()
}

func (m Model) renderTabBar() string {
	var tabs []string
	for i, name := range tabNames {
		if i == m.activeTab {
			tabs = append(tabs, activeTabStyle.Render("["+name+"]"))
		} else {
			tabs = append(tabs, inactiveTabStyle.Render(" "+name+" "))
		}
	}
	bar := lipgloss.JoinHorizontal(lipgloss.Top, tabs...)
	separator := strings.Repeat("─", max(0, m.width-lipgloss.Width(bar)))
	return bar + tabGapStyle.Render(separator)
}

func (m Model) renderActiveTab(height int) string {
	switch m.activeTab {
	case tabSessions:
		if !m.dataLoaded[tabSessions] {
			return renderLoading("sessions", height)
		}
		return m.sessions.view(m.width, height)
	case tabCheckpoints:
		if !m.dataLoaded[tabCheckpoints] {
			return renderLoading("checkpoints", height)
		}
		return m.checkpoints.view(m.width, height)
	case tabActive:
		if !m.dataLoaded[tabActive] {
			return renderLoading("active sessions", height)
		}
		return m.active.view(m.width, height)
	case tabSettings:
		if !m.dataLoaded[tabSettings] {
			return renderLoading("settings", height)
		}
		return m.settings.view(m.width, height)
	}
	return ""
}

func (m Model) renderStatusBar() string {
	if m.showHelp {
		return m.renderFullHelp()
	}
	hint := "Tab: switch | j/k: navigate | Enter: detail | ?: help | q: quit"
	if m.activeTab == tabCheckpoints {
		hint = "Tab: switch | j/k: navigate | Enter: detail | r: rewind | /: filter | ?: help | q: quit"
	}
	if m.activeTab == tabSessions {
		hint = "Tab: switch | j/k: navigate | Enter: detail | /: filter | ?: help | q: quit"
	}
	return statusBarStyle.Render(hint)
}

func (m Model) renderFullHelp() string {
	help := []string{
		"  Tab/Shift+Tab  Switch tabs",
		"  j/k, Up/Down   Navigate items",
		"  Enter          View detail / expand",
		"  Esc            Close detail / clear filter",
		"  /              Search / filter",
		"  r              Rewind (Checkpoints tab)",
		"  ?              Toggle this help",
		"  q, Ctrl+C      Quit",
	}
	return helpStyle.Render(strings.Join(help, "\n"))
}

func (m Model) contentHeight() int {
	// Tab bar (1) + separator (0, part of tab bar) + status bar (1) + margins
	overhead := 3
	if m.showHelp {
		overhead = 10 // help takes more space
	}
	h := m.height - overhead
	if h < 5 {
		h = 5
	}
	return h
}

func renderLoading(what string, height int) string {
	msg := dimStyle.Render(fmt.Sprintf("Loading %s...", what))
	// Center vertically
	padding := height / 2
	return strings.Repeat("\n", padding) + "  " + msg
}

// Run starts the dashboard TUI. Returns a RewindRequest if the user wants to rewind.
func Run() (*RewindRequest, error) {
	m := newModel()
	p := tea.NewProgram(m, tea.WithAltScreen())

	finalModel, err := p.Run()
	if err != nil {
		return nil, fmt.Errorf("dashboard TUI error: %w", err)
	}

	result := finalModel.(Model)
	if result.err != nil {
		return nil, result.err
	}

	return result.rewindReq, nil
}

package dashboard

import (
	"context"
	"fmt"
	"time"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

// Message types for async data loading.
type sessionsMsg struct {
	sessions []strategy.Session
	err      error
}

type checkpointsMsg struct {
	points []strategy.RewindPoint
	err    error
}

type activeSessionsMsg struct {
	states []*session.State
	err    error
}

type settingsDataMsg struct {
	settings *settings.EntireSettings
	agents   []agent.AgentName
	err      error
}

type rewindRequestMsg struct {
	pointID string
}

// Commands that load data asynchronously.

func loadSessionsCmd() tea.Msg {
	sessions, err := strategy.ListSessions()
	return sessionsMsg{sessions: sessions, err: err}
}

func loadCheckpointsCmd() tea.Msg {
	strat := getConfiguredStrategy()
	if strat == nil {
		return checkpointsMsg{err: fmt.Errorf("no strategy configured")}
	}
	points, err := strat.GetRewindPoints(100)
	return checkpointsMsg{points: points, err: err}
}

func loadActiveSessionsCmd() tea.Msg {
	store, err := session.NewStateStore()
	if err != nil {
		return activeSessionsMsg{err: err}
	}
	states, err := store.List(context.Background())
	return activeSessionsMsg{states: states, err: err}
}

func loadSettingsCmd() tea.Msg {
	s, err := settings.Load()
	if err != nil {
		return settingsDataMsg{err: err}
	}
	agents := agent.List()
	return settingsDataMsg{settings: s, agents: agents}
}

// getConfiguredStrategy loads settings and returns the configured strategy.
func getConfiguredStrategy() strategy.Strategy { //nolint:ireturn // factory pattern
	s, err := settings.Load()
	if err != nil {
		return strategy.Default()
	}
	strat, err := strategy.Get(s.Strategy)
	if err != nil {
		return strategy.Default()
	}
	return strat
}

// timeAgo formats a time as a human-readable relative duration.
func timeAgo(t time.Time) string {
	d := time.Since(t)
	switch {
	case d < time.Minute:
		return "just now"
	case d < time.Hour:
		m := int(d.Minutes())
		return fmt.Sprintf("%dm ago", m)
	case d < 24*time.Hour:
		h := int(d.Hours())
		return fmt.Sprintf("%dh ago", h)
	default:
		days := int(d.Hours() / 24)
		return fmt.Sprintf("%dd ago", days)
	}
}

// truncate shortens a string with an ellipsis if it exceeds maxLen.
func truncate(s string, maxLen int) string {
	runes := []rune(s)
	if len(runes) <= maxLen {
		return s
	}
	if maxLen < 3 {
		return string(runes[:maxLen])
	}
	return string(runes[:maxLen-3]) + "..."
}

package dashboard

import (
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

type settingsModel struct {
	data       *settings.EntireSettings
	agents     []agent.AgentName
	err        error
	scrollPos  int
	height     int
	lines      []string
}

func newSettingsModel() settingsModel {
	return settingsModel{}
}

func (m *settingsModel) setSize(_ int, height int) {
	m.height = height
}

func (m *settingsModel) setData(msg settingsDataMsg) {
	m.data = msg.settings
	m.agents = msg.agents
	m.err = msg.err
	m.buildLines()
}

func (m *settingsModel) buildLines() {
	if m.data == nil {
		return
	}

	var lines []string
	s := m.data

	lines = append(lines, titleStyle.Render("Configuration"))
	lines = append(lines, "")

	// Enabled/Disabled
	enabledStr := activePhaseStyle.Render("Enabled")
	if !s.Enabled {
		enabledStr = endedPhaseStyle.Render("Disabled")
	}
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Status:"), enabledStr))

	// Strategy
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Strategy:"), valueStyle.Render(s.Strategy)))

	// Log level
	logLevel := s.LogLevel
	if logLevel == "" {
		logLevel = "info (default)"
	}
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Log Level:"), valueStyle.Render(logLevel)))

	// Telemetry
	telemetryStr := dimStyle.Render("not configured")
	if s.Telemetry != nil {
		if *s.Telemetry {
			telemetryStr = activePhaseStyle.Render("opted in")
		} else {
			telemetryStr = endedPhaseStyle.Render("opted out")
		}
	}
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Telemetry:"), telemetryStr))

	// Summarize
	summarize := "disabled"
	if s.IsSummarizeEnabled() {
		summarize = "enabled"
	}
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Summarize:"), valueStyle.Render(summarize)))

	// Push sessions
	pushSessions := "enabled"
	if s.IsPushSessionsDisabled() {
		pushSessions = "disabled"
	}
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Push Sessions:"), valueStyle.Render(pushSessions)))

	lines = append(lines, "")
	lines = append(lines, titleStyle.Render("Installed Agents"))
	lines = append(lines, "")

	if len(m.agents) == 0 {
		lines = append(lines, "  "+dimStyle.Render("No agents registered"))
	} else {
		for _, name := range m.agents {
			ag, err := agent.Get(name)
			if err != nil {
				lines = append(lines, fmt.Sprintf("  %s %s", dimStyle.Render("-"), valueStyle.Render(string(name))))
				continue
			}

			hooksStr := dimStyle.Render("no hooks")
			if hs, ok := ag.(agent.HookSupport); ok {
				if hs.AreHooksInstalled() {
					hooksStr = activePhaseStyle.Render("hooks installed")
				} else {
					hooksStr = idlePhaseStyle.Render("hooks not installed")
				}
			}

			lines = append(lines, fmt.Sprintf("  %s  %s  %s",
				labelStyle.Render(string(ag.Type())),
				dimStyle.Render("("+string(name)+")"),
				hooksStr,
			))
		}
	}

	// Strategy options
	if len(s.StrategyOptions) > 0 {
		lines = append(lines, "")
		lines = append(lines, titleStyle.Render("Strategy Options"))
		lines = append(lines, "")
		for k, v := range s.StrategyOptions {
			lines = append(lines, fmt.Sprintf("  %s  %v", labelStyle.Render(k+":"), v))
		}
	}

	m.lines = lines
}

func (m settingsModel) update(msg tea.Msg) (settingsModel, tea.Cmd) {
	if keyMsg, ok := msg.(tea.KeyMsg); ok {
		switch keyMsg.String() {
		case "j", "down":
			if m.scrollPos < len(m.lines)-m.height {
				m.scrollPos++
			}
		case "k", "up":
			if m.scrollPos > 0 {
				m.scrollPos--
			}
		}
	}
	return m, nil
}

func (m settingsModel) view(_ int, height int) string {
	if m.err != nil {
		return errorStyle.Render(fmt.Sprintf("Error loading settings: %v", m.err))
	}
	if m.data == nil {
		return dimStyle.Render("  No settings data available")
	}

	// Apply scroll
	start := m.scrollPos
	end := start + height
	if end > len(m.lines) {
		end = len(m.lines)
	}
	if start > len(m.lines) {
		start = len(m.lines)
	}

	visible := m.lines[start:end]
	return strings.Join(visible, "\n")
}

package dashboard

import (
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/entireio/cli/cmd/entire/cli/session"
)

type activeModel struct {
	states     []*session.State
	err        error
	cursor     int
	scrollPos  int
	width      int
	height     int
	showDetail bool
}

func newActiveModel() activeModel {
	return activeModel{}
}

func (m *activeModel) setSize(width, height int) {
	m.width = width
	m.height = height
}

func (m *activeModel) setSessions(states []*session.State) {
	// Filter to active sessions only (no EndedAt)
	var active []*session.State
	for _, s := range states {
		if s.EndedAt == nil {
			active = append(active, s)
		}
	}
	m.states = active
}

func (m activeModel) update(msg tea.Msg) (activeModel, tea.Cmd) {
	if keyMsg, ok := msg.(tea.KeyMsg); ok {
		switch keyMsg.String() {
		case "j", "down":
			if m.showDetail {
				m.scrollPos++
			} else if m.cursor < len(m.states)-1 {
				m.cursor++
			}
		case "k", "up":
			if m.showDetail {
				if m.scrollPos > 0 {
					m.scrollPos--
				}
			} else if m.cursor > 0 {
				m.cursor--
			}
		case "enter":
			if len(m.states) > 0 {
				m.showDetail = !m.showDetail
				m.scrollPos = 0
			}
		case "esc":
			m.showDetail = false
			m.scrollPos = 0
		}
	}
	return m, nil
}

func (m activeModel) view(width, height int) string {
	if m.err != nil {
		return errorStyle.Render(fmt.Sprintf("Error loading active sessions: %v", m.err))
	}
	if len(m.states) == 0 {
		return dimStyle.Render("  No active sessions")
	}

	if m.showDetail && m.cursor < len(m.states) {
		return m.renderDetail(width, height)
	}

	return m.renderList(width, height)
}

func (m activeModel) renderList(_ int, height int) string {
	var lines []string

	lines = append(lines, fmt.Sprintf("  %s (%d)",
		titleStyle.Render("Active Sessions"),
		len(m.states)))
	lines = append(lines, "")

	// Table header
	header := fmt.Sprintf("  %-9s  %-8s  %-14s  %-12s  %-12s  %s",
		labelStyle.Render("ID"),
		labelStyle.Render("Phase"),
		labelStyle.Render("Agent"),
		labelStyle.Render("Started"),
		labelStyle.Render("Last Active"),
		labelStyle.Render("Prompt"),
	)
	lines = append(lines, header)
	lines = append(lines, "  "+dimStyle.Render(strings.Repeat("─", 80)))

	for i, s := range m.states {
		shortID := s.SessionID
		if len(shortID) > 7 {
			shortID = shortID[:7]
		}

		phase := renderPhase(s.Phase)

		agentLabel := string(s.AgentType)
		if agentLabel == "" {
			agentLabel = "(unknown)"
		}
		agentLabel = truncate(agentLabel, 12)

		started := timeAgo(s.StartedAt)

		lastActive := "-"
		if s.LastInteractionTime != nil {
			lastActive = timeAgo(*s.LastInteractionTime)
		}

		prompt := truncate(s.FirstPrompt, 30)
		if prompt == "" {
			prompt = dimStyle.Render("-")
		}

		line := fmt.Sprintf("  %-9s  %-18s  %-14s  %-12s  %-12s  %s",
			shortID, phase, agentLabel, started, lastActive, prompt)

		if i == m.cursor {
			line = selectedItemStyle.Render(line)
		}

		lines = append(lines, line)
	}

	// Apply scroll to fit height
	if len(lines) > height {
		start := 0
		if m.cursor > height-4 {
			start = m.cursor - height + 4
		}
		end := start + height
		if end > len(lines) {
			end = len(lines)
		}
		lines = lines[start:end]
	}

	return strings.Join(lines, "\n")
}

func (m activeModel) renderDetail(_ int, height int) string {
	s := m.states[m.cursor]

	var lines []string
	lines = append(lines, titleStyle.Render("Session Detail"))
	lines = append(lines, "")
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Session ID:"), valueStyle.Render(s.SessionID)))
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Phase:"), renderPhase(s.Phase)))
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Agent:"), valueStyle.Render(string(s.AgentType))))
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Started:"), valueStyle.Render(s.StartedAt.Format("2006-01-02 15:04:05"))))

	if s.LastInteractionTime != nil {
		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Last Active:"), valueStyle.Render(s.LastInteractionTime.Format("2006-01-02 15:04:05"))))
	}

	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Base Commit:"), valueStyle.Render(truncate(s.BaseCommit, 12))))
	lines = append(lines, fmt.Sprintf("  %s  %d", labelStyle.Render("Step Count:"), s.StepCount))

	if s.WorktreePath != "" {
		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Worktree:"), valueStyle.Render(s.WorktreePath)))
	}

	if s.FirstPrompt != "" {
		lines = append(lines, "")
		lines = append(lines, labelStyle.Render("  First Prompt:"))
		lines = append(lines, "  "+valueStyle.Render(s.FirstPrompt))
	}

	if s.TokenUsage != nil {
		lines = append(lines, "")
		lines = append(lines, labelStyle.Render("  Token Usage:"))
		lines = append(lines, fmt.Sprintf("    Input:  %d", s.TokenUsage.InputTokens))
		lines = append(lines, fmt.Sprintf("    Output: %d", s.TokenUsage.OutputTokens))
	}

	if len(s.FilesTouched) > 0 {
		lines = append(lines, "")
		lines = append(lines, fmt.Sprintf("  %s (%d files)", labelStyle.Render("Files Touched:"), len(s.FilesTouched)))
		for _, f := range s.FilesTouched {
			lines = append(lines, "    "+dimStyle.Render(f))
		}
	}

	lines = append(lines, "")
	lines = append(lines, dimStyle.Render("  Press Esc to go back"))

	// Apply scroll
	start := m.scrollPos
	end := start + height
	if end > len(lines) {
		end = len(lines)
	}
	if start >= len(lines) {
		start = max(0, len(lines)-1)
	}

	return strings.Join(lines[start:end], "\n")
}

func renderPhase(p session.Phase) string {
	switch p {
	case session.PhaseActive:
		return activePhaseStyle.Render("ACTIVE")
	case session.PhaseIdle:
		return idlePhaseStyle.Render("IDLE")
	case session.PhaseEnded:
		return endedPhaseStyle.Render("ENDED")
	default:
		return idlePhaseStyle.Render("IDLE")
	}
}

package dashboard

import (
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

type sessionsModel struct {
	sessions   []strategy.Session
	filtered   []strategy.Session
	err        error
	cursor     int
	scrollPos  int
	width      int
	height     int
	showDetail bool
	filtering  bool
	filter     string
}

func newSessionsModel() sessionsModel {
	return sessionsModel{}
}

func (m *sessionsModel) setSize(width, height int) {
	m.width = width
	m.height = height
}

func (m *sessionsModel) setSessions(sessions []strategy.Session) {
	m.sessions = sessions
	m.applyFilter()
}

func (m *sessionsModel) applyFilter() {
	if m.filter == "" {
		m.filtered = m.sessions
		return
	}
	lower := strings.ToLower(m.filter)
	var filtered []strategy.Session
	for _, s := range m.sessions {
		if strings.Contains(strings.ToLower(s.ID), lower) ||
			strings.Contains(strings.ToLower(s.Description), lower) ||
			strings.Contains(strings.ToLower(s.Strategy), lower) {
			filtered = append(filtered, s)
		}
	}
	m.filtered = filtered
	if m.cursor >= len(m.filtered) {
		m.cursor = max(0, len(m.filtered)-1)
	}
}

func (m sessionsModel) update(msg tea.Msg) (sessionsModel, tea.Cmd) {
	keyMsg, ok := msg.(tea.KeyMsg)
	if !ok {
		return m, nil
	}

	if m.filtering {
		switch keyMsg.String() {
		case "esc":
			m.filtering = false
			m.filter = ""
			m.applyFilter()
		case "enter":
			m.filtering = false
		case "backspace":
			if len(m.filter) > 0 {
				m.filter = m.filter[:len(m.filter)-1]
				m.applyFilter()
			}
		default:
			if len(keyMsg.String()) == 1 {
				m.filter += keyMsg.String()
				m.applyFilter()
			}
		}
		return m, nil
	}

	switch keyMsg.String() {
	case "j", "down":
		if m.showDetail {
			m.scrollPos++
		} else if m.cursor < len(m.filtered)-1 {
			m.cursor++
		}
	case "k", "up":
		if m.showDetail {
			if m.scrollPos > 0 {
				m.scrollPos--
			}
		} else if m.cursor > 0 {
			m.cursor--
		}
	case "enter":
		if len(m.filtered) > 0 {
			m.showDetail = !m.showDetail
			m.scrollPos = 0
		}
	case "esc":
		if m.showDetail {
			m.showDetail = false
			m.scrollPos = 0
		} else if m.filter != "" {
			m.filter = ""
			m.applyFilter()
		}
	case "/":
		m.filtering = true
	}

	return m, nil
}

func (m sessionsModel) view(width, height int) string {
	if m.err != nil {
		return errorStyle.Render(fmt.Sprintf("Error loading sessions: %v", m.err))
	}

	if m.showDetail && m.cursor < len(m.filtered) {
		return m.renderDetail(width, height)
	}

	return m.renderList(width, height)
}

func (m sessionsModel) renderList(_ int, height int) string {
	var lines []string

	// Header
	headerText := fmt.Sprintf("Sessions (%d)", len(m.filtered))
	if m.filter != "" {
		headerText += fmt.Sprintf("  filter: %s", m.filter)
	}
	if m.filtering {
		headerText += dimStyle.Render("  type to filter, Enter to confirm, Esc to cancel")
	}
	lines = append(lines, "  "+titleStyle.Render(headerText))
	lines = append(lines, "")

	if len(m.filtered) == 0 {
		lines = append(lines, "  "+dimStyle.Render("No sessions found"))
		return strings.Join(lines, "\n")
	}

	for i, s := range m.filtered {
		shortID := s.ID
		if len(shortID) > 12 {
			shortID = shortID[:12]
		}

		desc := s.Description
		if desc == "" || desc == strategy.NoDescription {
			desc = dimStyle.Render("(no description)")
		} else {
			desc = truncate(desc, 50)
		}

		age := timeAgo(s.StartTime)
		cpCount := len(s.Checkpoints)
		stratName := s.Strategy
		if stratName == "" {
			stratName = "-"
		}

		line := fmt.Sprintf("  %-12s  %s  %s  %s  %d cp",
			shortID, desc, dimStyle.Render(stratName), dimStyle.Render(age), cpCount)

		if i == m.cursor {
			line = selectedItemStyle.Render(line)
		}

		lines = append(lines, line)
	}

	// Scroll if needed
	visibleStart := 0
	headerLines := 2
	maxVisible := height - headerLines
	if maxVisible < 1 {
		maxVisible = 1
	}

	if m.cursor-visibleStart >= maxVisible {
		visibleStart = m.cursor - maxVisible + 1
	}

	result := lines[:headerLines] // always show header
	dataLines := lines[headerLines:]
	end := visibleStart + maxVisible
	if end > len(dataLines) {
		end = len(dataLines)
	}
	if visibleStart < len(dataLines) {
		result = append(result, dataLines[visibleStart:end]...)
	}

	return strings.Join(result, "\n")
}

func (m sessionsModel) renderDetail(_ int, height int) string {
	s := m.filtered[m.cursor]

	var lines []string
	lines = append(lines, titleStyle.Render("Session Detail"))
	lines = append(lines, "")
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("ID:"), valueStyle.Render(s.ID)))
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Description:"), valueStyle.Render(s.Description)))
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Strategy:"), valueStyle.Render(s.Strategy)))
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Started:"), valueStyle.Render(s.StartTime.Format("2006-01-02 15:04:05"))))
	lines = append(lines, "")

	lines = append(lines, fmt.Sprintf("  %s (%d)", labelStyle.Render("Checkpoints:"), len(s.Checkpoints)))
	lines = append(lines, "")

	for _, cp := range s.Checkpoints {
		cpType := "session"
		if cp.IsTaskCheckpoint {
			cpType = "task"
		}
		cpID := cp.CheckpointID.String()
		if cpID == "" {
			cpID = "(none)"
		}

		lines = append(lines, fmt.Sprintf("    %s  %s  %s  %s",
			dimStyle.Render(cpID),
			dimStyle.Render("["+cpType+"]"),
			cp.Message,
			dimStyle.Render(timeAgo(cp.Timestamp)),
		))
	}

	lines = append(lines, "")
	lines = append(lines, dimStyle.Render("  Press Esc to go back"))

	// Apply scroll
	start := m.scrollPos
	end := start + height
	if end > len(lines) {
		end = len(lines)
	}
	if start >= len(lines) {
		start = max(0, len(lines)-1)
	}

	return strings.Join(lines[start:end], "\n")
}

package dashboard

import (
	"fmt"
	"strings"

	tea "github.com/charmbracelet/bubbletea"

	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

type checkpointsModel struct {
	points     []strategy.RewindPoint
	filtered   []strategy.RewindPoint
	err        error
	cursor     int
	scrollPos  int
	width      int
	height     int
	showDetail bool
	filtering  bool
	filter     string
	confirming bool // rewind confirmation dialog
}

func newCheckpointsModel() checkpointsModel {
	return checkpointsModel{}
}

func (m *checkpointsModel) setSize(width, height int) {
	m.width = width
	m.height = height
}

func (m *checkpointsModel) setCheckpoints(points []strategy.RewindPoint) {
	m.points = points
	m.applyFilter()
}

func (m *checkpointsModel) applyFilter() {
	if m.filter == "" {
		m.filtered = m.points
		return
	}
	lower := strings.ToLower(m.filter)
	var filtered []strategy.RewindPoint
	for _, p := range m.points {
		if strings.Contains(strings.ToLower(p.ID), lower) ||
			strings.Contains(strings.ToLower(p.Message), lower) ||
			strings.Contains(strings.ToLower(p.SessionPrompt), lower) ||
			strings.Contains(strings.ToLower(p.CheckpointID.String()), lower) {
			filtered = append(filtered, p)
		}
	}
	m.filtered = filtered
	if m.cursor >= len(m.filtered) {
		m.cursor = max(0, len(m.filtered)-1)
	}
}

func (m checkpointsModel) update(msg tea.Msg) (checkpointsModel, tea.Cmd) {
	keyMsg, ok := msg.(tea.KeyMsg)
	if !ok {
		return m, nil
	}

	// Handle confirmation dialog
	if m.confirming {
		switch keyMsg.String() {
		case "y", "Y":
			m.confirming = false
			if m.cursor < len(m.filtered) {
				point := m.filtered[m.cursor]
				return m, func() tea.Msg {
					return rewindRequestMsg{pointID: point.ID}
				}
			}
		case "n", "N", "esc":
			m.confirming = false
		}
		return m, nil
	}

	// Handle filter input
	if m.filtering {
		switch keyMsg.String() {
		case "esc":
			m.filtering = false
			m.filter = ""
			m.applyFilter()
		case "enter":
			m.filtering = false
		case "backspace":
			if len(m.filter) > 0 {
				m.filter = m.filter[:len(m.filter)-1]
				m.applyFilter()
			}
		default:
			if len(keyMsg.String()) == 1 {
				m.filter += keyMsg.String()
				m.applyFilter()
			}
		}
		return m, nil
	}

	switch keyMsg.String() {
	case "j", "down":
		if m.showDetail {
			m.scrollPos++
		} else if m.cursor < len(m.filtered)-1 {
			m.cursor++
		}
	case "k", "up":
		if m.showDetail {
			if m.scrollPos > 0 {
				m.scrollPos--
			}
		} else if m.cursor > 0 {
			m.cursor--
		}
	case "enter":
		if len(m.filtered) > 0 {
			m.showDetail = !m.showDetail
			m.scrollPos = 0
		}
	case "esc":
		if m.showDetail {
			m.showDetail = false
			m.scrollPos = 0
		} else if m.filter != "" {
			m.filter = ""
			m.applyFilter()
		}
	case "/":
		m.filtering = true
	case "r":
		if len(m.filtered) > 0 && !m.showDetail {
			m.confirming = true
		}
	}

	return m, nil
}

func (m checkpointsModel) view(width, height int) string {
	if m.err != nil {
		return errorStyle.Render(fmt.Sprintf("Error loading checkpoints: %v", m.err))
	}

	if m.confirming && m.cursor < len(m.filtered) {
		return m.renderConfirmation(width, height)
	}

	if m.showDetail && m.cursor < len(m.filtered) {
		return m.renderDetail(width, height)
	}

	return m.renderList(width, height)
}

func (m checkpointsModel) renderList(_ int, height int) string {
	var lines []string

	// Header
	headerText := fmt.Sprintf("Checkpoints (%d)", len(m.filtered))
	if m.filter != "" {
		headerText += fmt.Sprintf("  filter: %s", m.filter)
	}
	if m.filtering {
		headerText += dimStyle.Render("  type to filter, Enter to confirm, Esc to cancel")
	}
	lines = append(lines, "  "+titleStyle.Render(headerText))
	lines = append(lines, "")

	if len(m.filtered) == 0 {
		lines = append(lines, "  "+dimStyle.Render("No checkpoints found"))
		return strings.Join(lines, "\n")
	}

	for i, p := range m.filtered {
		cpType := "session"
		if p.IsTaskCheckpoint {
			cpType = "task"
		}
		if p.IsLogsOnly {
			cpType = "committed"
		}

		cpID := p.CheckpointID.String()
		if cpID == "" {
			cpID = truncate(p.ID, 12)
		}

		prompt := truncate(p.SessionPrompt, 40)
		if prompt == "" {
			prompt = truncate(p.Message, 40)
		}

		agentStr := string(p.Agent)
		if agentStr == "" {
			agentStr = "-"
		}

		line := fmt.Sprintf("  %-12s  %-10s  %-14s  %-10s  %s",
			cpID,
			dimStyle.Render("["+cpType+"]"),
			agentStr,
			dimStyle.Render(timeAgo(p.Date)),
			prompt,
		)

		if i == m.cursor {
			line = selectedItemStyle.Render(line)
		}

		lines = append(lines, line)
	}

	// Scroll
	visibleStart := 0
	headerLines := 2
	maxVisible := height - headerLines
	if maxVisible < 1 {
		maxVisible = 1
	}

	if m.cursor-visibleStart >= maxVisible {
		visibleStart = m.cursor - maxVisible + 1
	}

	result := lines[:headerLines]
	dataLines := lines[headerLines:]
	end := visibleStart + maxVisible
	if end > len(dataLines) {
		end = len(dataLines)
	}
	if visibleStart < len(dataLines) {
		result = append(result, dataLines[visibleStart:end]...)
	}

	return strings.Join(result, "\n")
}

func (m checkpointsModel) renderDetail(_ int, height int) string {
	p := m.filtered[m.cursor]

	var lines []string
	lines = append(lines, titleStyle.Render("Checkpoint Detail"))
	lines = append(lines, "")
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("ID:"), valueStyle.Render(p.ID)))

	cpID := p.CheckpointID.String()
	if cpID != "" {
		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Checkpoint ID:"), valueStyle.Render(cpID)))
	}

	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Date:"), valueStyle.Render(p.Date.Format("2006-01-02 15:04:05"))))
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Message:"), valueStyle.Render(p.Message)))

	if string(p.Agent) != "" {
		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Agent:"), valueStyle.Render(string(p.Agent))))
	}

	cpType := "Session checkpoint"
	if p.IsTaskCheckpoint {
		cpType = "Task checkpoint"
	}
	if p.IsLogsOnly {
		cpType = "Committed (logs only)"
	}
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Type:"), valueStyle.Render(cpType)))

	if p.SessionID != "" {
		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Session:"), valueStyle.Render(p.SessionID)))
	}

	if p.SessionPrompt != "" {
		lines = append(lines, "")
		lines = append(lines, labelStyle.Render("  Prompt:"))
		lines = append(lines, "  "+valueStyle.Render(p.SessionPrompt))
	}

	if p.ToolUseID != "" {
		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Tool Use ID:"), valueStyle.Render(p.ToolUseID)))
	}

	if p.SessionCount > 1 {
		lines = append(lines, fmt.Sprintf("  %s  %d", labelStyle.Render("Sessions:"), p.SessionCount))
		for i, sid := range p.SessionIDs {
			prompt := ""
			if i < len(p.SessionPrompts) {
				prompt = truncate(p.SessionPrompts[i], 40)
			}
			lines = append(lines, fmt.Sprintf("    %s  %s", dimStyle.Render(truncate(sid, 20)), prompt))
		}
	}

	lines = append(lines, "")
	lines = append(lines, dimStyle.Render("  Press Esc to go back"))

	// Apply scroll
	start := m.scrollPos
	end := start + height
	if end > len(lines) {
		end = len(lines)
	}
	if start >= len(lines) {
		start = max(0, len(lines)-1)
	}

	return strings.Join(lines[start:end], "\n")
}

func (m checkpointsModel) renderConfirmation(_ int, _ int) string {
	p := m.filtered[m.cursor]

	var lines []string
	lines = append(lines, "")
	lines = append(lines, confirmStyle.Render("  Rewind to this checkpoint?"))
	lines = append(lines, "")

	cpID := p.CheckpointID.String()
	if cpID == "" {
		cpID = truncate(p.ID, 20)
	}
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Checkpoint:"), valueStyle.Render(cpID)))
	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Date:"), valueStyle.Render(p.Date.Format("2006-01-02 15:04:05"))))
	if p.SessionPrompt != "" {
		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Prompt:"), valueStyle.Render(truncate(p.SessionPrompt, 50))))
	}

	if p.IsLogsOnly {
		lines = append(lines, "")
		lines = append(lines, "  "+idlePhaseStyle.Render("This is a logs-only checkpoint. Only session logs will be restored."))
	}

	lines = append(lines, "")
	lines = append(lines, "  "+confirmStyle.Render("Press y to confirm, n or Esc to cancel"))

	return strings.Join(lines, "\n")
}

package dashboard

import (
	"context"
	"fmt"
	"io"
	"os"
	"strings"

	"github.com/charmbracelet/huh"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
)

// RunAccessible runs a text-based menu for accessibility mode.
func RunAccessible(w io.Writer, _ io.Writer) error {
	for {
		var choice string

		form := huh.NewForm(
			huh.NewGroup(
				huh.NewSelect[string]().
					Title("Entire Dashboard").
					Options(
						huh.NewOption("View sessions", "sessions"),
						huh.NewOption("View checkpoints", "checkpoints"),
						huh.NewOption("View active sessions", "active"),
						huh.NewOption("View settings", "settings"),
						huh.NewOption("Quit", "quit"),
					).
					Value(&choice),
			),
		).WithAccessible(true)

		if err := form.Run(); err != nil {
			return fmt.Errorf("menu selection failed: %w", err)
		}

		switch choice {
		case "sessions":
			if err := showAccessibleSessions(w); err != nil {
				fmt.Fprintf(w, "Error: %v\n", err)
			}
		case "checkpoints":
			if err := showAccessibleCheckpoints(w); err != nil {
				fmt.Fprintf(w, "Error: %v\n", err)
			}
		case "active":
			if err := showAccessibleActive(w); err != nil {
				fmt.Fprintf(w, "Error: %v\n", err)
			}
		case "settings":
			if err := showAccessibleSettings(w); err != nil {
				fmt.Fprintf(w, "Error: %v\n", err)
			}
		case "quit":
			return nil
		}

		fmt.Fprintln(w)
	}
}

func showAccessibleSessions(w io.Writer) error {
	sessions, err := strategy.ListSessions()
	if err != nil {
		return fmt.Errorf("loading sessions: %w", err)
	}

	if len(sessions) == 0 {
		fmt.Fprintln(w, "\nNo sessions found.")
		return nil
	}

	fmt.Fprintf(w, "\nSessions (%d):\n", len(sessions))
	fmt.Fprintln(w, strings.Repeat("-", 60))

	for _, s := range sessions {
		shortID := s.ID
		if len(shortID) > 12 {
			shortID = shortID[:12]
		}
		desc := s.Description
		if desc == "" || desc == strategy.NoDescription {
			desc = "(no description)"
		} else {
			desc = truncate(desc, 50)
		}
		fmt.Fprintf(w, "  %-12s  %s  %s  %d checkpoints\n",
			shortID, desc, timeAgo(s.StartTime), len(s.Checkpoints))
	}

	return nil
}

func showAccessibleCheckpoints(w io.Writer) error {
	strat := getConfiguredStrategy()
	if strat == nil {
		return fmt.Errorf("no strategy configured")
	}

	points, err := strat.GetRewindPoints(50)
	if err != nil {
		return fmt.Errorf("loading checkpoints: %w", err)
	}

	if len(points) == 0 {
		fmt.Fprintln(w, "\nNo checkpoints found.")
		return nil
	}

	fmt.Fprintf(w, "\nCheckpoints (%d):\n", len(points))
	fmt.Fprintln(w, strings.Repeat("-", 60))

	for _, p := range points {
		cpType := "session"
		if p.IsTaskCheckpoint {
			cpType = "task"
		}
		if p.IsLogsOnly {
			cpType = "committed"
		}

		cpID := p.CheckpointID.String()
		if cpID == "" {
			cpID = truncate(p.ID, 12)
		}

		prompt := truncate(p.SessionPrompt, 40)
		if prompt == "" {
			prompt = truncate(p.Message, 40)
		}

		fmt.Fprintf(w, "  %-12s  [%-9s]  %-10s  %s\n",
			cpID, cpType, timeAgo(p.Date), prompt)
	}

	return nil
}

func showAccessibleActive(w io.Writer) error {
	store, err := session.NewStateStore()
	if err != nil {
		return fmt.Errorf("creating state store: %w", err)
	}

	states, err := store.List(context.Background())
	if err != nil {
		return fmt.Errorf("listing sessions: %w", err)
	}

	// Filter active
	var active []*session.State
	for _, s := range states {
		if s.EndedAt == nil {
			active = append(active, s)
		}
	}

	if len(active) == 0 {
		fmt.Fprintln(w, "\nNo active sessions.")
		return nil
	}

	fmt.Fprintf(w, "\nActive Sessions (%d):\n", len(active))
	fmt.Fprintln(w, strings.Repeat("-", 60))

	for _, s := range active {
		shortID := s.SessionID
		if len(shortID) > 7 {
			shortID = shortID[:7]
		}

		agentLabel := string(s.AgentType)
		if agentLabel == "" {
			agentLabel = "(unknown)"
		}

		phase := string(s.Phase)
		if phase == "" {
			phase = "idle"
		}

		prompt := truncate(s.FirstPrompt, 40)

		fmt.Fprintf(w, "  %-9s  %-8s  %-14s  %s  %s\n",
			shortID, phase, agentLabel, timeAgo(s.StartedAt), prompt)
	}

	return nil
}

func showAccessibleSettings(w io.Writer) error {
	s, err := settings.Load()
	if err != nil {
		return fmt.Errorf("loading settings: %w", err)
	}

	fmt.Fprintln(w, "\nSettings:")
	fmt.Fprintln(w, strings.Repeat("-", 40))

	enabledStr := "Enabled"
	if !s.Enabled {
		enabledStr = "Disabled"
	}
	fmt.Fprintf(w, "  Status:    %s\n", enabledStr)
	fmt.Fprintf(w, "  Strategy:  %s\n", s.Strategy)

	logLevel := s.LogLevel
	if logLevel == "" {
		logLevel = "info (default)"
	}
	fmt.Fprintf(w, "  Log Level: %s\n", logLevel)

	telemetryStr := "not configured"
	if s.Telemetry != nil {
		if *s.Telemetry {
			telemetryStr = "opted in"
		} else {
			telemetryStr = "opted out"
		}
	}
	fmt.Fprintf(w, "  Telemetry: %s\n", telemetryStr)

	fmt.Fprintln(w, "\nInstalled Agents:")
	agents := agent.List()
	if len(agents) == 0 {
		fmt.Fprintln(w, "  (none)")
	}
	for _, name := range agents {
		ag, err := agent.Get(name)
		if err != nil {
			continue
		}
		hooksStr := "no hooks"
		if hs, ok := ag.(agent.HookSupport); ok {
			if hs.AreHooksInstalled() {
				hooksStr = "hooks installed"
			} else {
				hooksStr = "hooks not installed"
			}
		}
		fmt.Fprintf(w, "  %s (%s) - %s\n", ag.Type(), name, hooksStr)
	}

	return nil
}

// isAccessibleMode checks if ACCESSIBLE env var is set.
func isAccessibleMode() bool {
	return os.Getenv("ACCESSIBLE") != ""
}

package cli

import (
	"errors"
	"fmt"

	"github.com/entireio/cli/cmd/entire/cli/dashboard"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/spf13/cobra"
)

func newDashboardCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "dashboard",
		Short: "Open interactive session dashboard",
		Long: `Interactive TUI dashboard for browsing sessions, checkpoints,
active sessions, and settings.

Navigate with Tab/Shift+Tab between tabs, j/k or arrow keys to move,
Enter to view details, and q to quit.

In the Checkpoints tab, press r to rewind to a selected checkpoint.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			// Check if we're in a git repository
			if _, err := paths.RepoRoot(); err != nil {
				cmd.SilenceUsage = true
				fmt.Fprintln(cmd.ErrOrStderr(), "Not a git repository. Please run from within a git repository.")
				return NewSilentError(errors.New("not a git repository"))
			}

			// Check if Entire is disabled
			if checkDisabledGuard(cmd.OutOrStdout()) {
				return nil
			}

			// Accessible mode uses text-based menu
			if IsAccessibleMode() {
				return dashboard.RunAccessible(cmd.OutOrStdout(), cmd.ErrOrStderr())
			}

			// Run TUI dashboard
			rewindReq, err := dashboard.Run()
			if err != nil {
				return fmt.Errorf("dashboard error: %w", err)
			}

			// Handle rewind request from dashboard
			if rewindReq != nil {
				return performRewindFromDashboard(cmd, rewindReq.PointID)
			}

			return nil
		},
	}
}

// performRewindFromDashboard executes a rewind after the dashboard TUI exits.
func performRewindFromDashboard(cmd *cobra.Command, pointID string) error {
	strat := GetStrategy()

	// Check if rewind is possible
	canRewind, reason, err := strat.CanRewind()
	if err != nil {
		return fmt.Errorf("failed to check rewind status: %w", err)
	}
	if !canRewind {
		fmt.Fprintln(cmd.OutOrStdout(), reason)
		return nil
	}

	// Find the matching rewind point
	points, err := strat.GetRewindPoints(100)
	if err != nil {
		return fmt.Errorf("failed to get rewind points: %w", err)
	}

	var target *strategy.RewindPoint
	for i := range points {
		if points[i].ID == pointID {
			target = &points[i]
			break
		}
	}

	if target == nil {
		return fmt.Errorf("rewind point %s not found", pointID)
	}

	// Perform the rewind
	if err := strat.Rewind(*target); err != nil {
		return fmt.Errorf("rewind failed: %w", err)
	}

	fmt.Fprintln(cmd.OutOrStdout(), "Successfully rewound to checkpoint.")

	// Print resume command if agent info available
	if target.Agent != "" {
		resumeCmd := formatResumeCommand(target.Agent, target.SessionID)
		if resumeCmd != "" {
			fmt.Fprintf(cmd.OutOrStdout(), "\nTo resume: %s\n", resumeCmd)
		}
	}

	return nil
}

// formatResumeCommand generates the resume command for an agent.
func formatResumeCommand(agentType agent.AgentType, sessionID string) string {
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return ""
	}
	return ag.FormatResumeCommand(sessionID)
}

