127→		}
128→
129→		prompt := truncate(s.FirstPrompt, 30)
130→		if prompt == "" {
131→			prompt = dimStyle.Render("-")
132→		}
133→
134→		line := fmt.Sprintf("  %-9s  %-18s  %-14s  %-12s  %-12s  %s",
135→			shortID, phase, agentLabel, started, lastActive, prompt)
136→
137→		if i == m.cursor {
138→			line = selectedItemStyle.Render(line)
139→		}
140→
141→		lines = append(lines, line)
142→	}
143→
144→	// Apply scroll to fit height
145→	if len(lines) > height {
146→		start := 0
147→		if m.cursor > height-4 {
148→			start = m.cursor - height + 4
149→		}
150→		end := start + height
151→		if end > len(lines) {
152→			end = len(lines)
153→		}
154→		lines = lines[start:end]
155→	}
156→
157→	return strings.Join(lines, "\n")
158→}
