160→func (m activeModel) renderDetail(_ int, height int) string {
161→	s := m.states[m.cursor]
162→
163→	var lines []string
164→	lines = append(lines, titleStyle.Render("Session Detail"))
165→	lines = append(lines, "")
166→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Session ID:"), valueStyle.Render(s.SessionID)))
167→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Phase:"), renderPhase(s.Phase)))
168→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Agent:"), valueStyle.Render(string(s.AgentType))))
169→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Started:"), valueStyle.Render(s.StartedAt.Format("2006-01-02 15:04:05"))))
170→
171→	if s.LastInteractionTime != nil {
172→		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Last Active:"), valueStyle.Render(s.LastInteractionTime.Format("2006-01-02 15:04:05"))))
173→	}
174→
175→	lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Base Commit:"), valueStyle.Render(truncate(s.BaseCommit, 12))))
176→	lines = append(lines, fmt.Sprintf("  %s  %d", labelStyle.Render("Step Count:"), s.StepCount))
177→
178→	if s.WorktreePath != "" {
179→		lines = append(lines, fmt.Sprintf("  %s  %s", labelStyle.Render("Worktree:"), valueStyle.Render(s.WorktreePath)))
180→	}
181→
182→	if s.FirstPrompt != "" {
183→		lines = append(lines, "")
184→		lines = append(lines, labelStyle.Render("  First Prompt:"))
185→		lines = append(lines, "  "+valueStyle.Render(s.FirstPrompt))
186→	}
187→
188→	if s.TokenUsage != nil {
189→		lines = append(lines, "")
190→		lines = append(lines, labelStyle.Render("  Token Usage:"))
191→		lines = append(lines, fmt.Sprintf("    Input:  %d", s.TokenUsage.InputTokens))
192→		lines = append(lines, fmt.Sprintf("    Output: %d", s.TokenUsage.OutputTokens))
193→	}
194→
195→	if len(s.FilesTouched) > 0 {
196→		lines = append(lines, "")
197→		lines = append(lines, fmt.Sprintf("  %s (%d files)", labelStyle.Render("Files Touched:"), len(s.FilesTouched)))
198→		for _, f := range s.FilesTouched {
199→			lines = append(lines, "    "+dimStyle.Render(f))
200→		}
201→	}
202→
203→	lines = append(lines, "")
204→	lines = append(lines, dimStyle.Render("  Press Esc to go back"))
205→
206→	// Apply scroll
207→	start := m.scrollPos
208→	end := start + height
209→	if end > len(lines) {
210→		end = len(lines)
211→	}
212→	if start >= len(lines) {
213→		start = max(0, len(lines)-1)
214→	}
215→
216→	return strings.Join(lines[start:end], "\n")
217→}
