219→func renderPhase(p session.Phase) string {
220→	switch p {
221→	case session.PhaseActive:
222→		return activePhaseStyle.Render("ACTIVE")
223→	case session.PhaseIdle:
224→		return idlePhaseStyle.Render("IDLE")
225→	case session.PhaseEnded:
226→		return endedPhaseStyle.Render("ENDED")
227→	default:
228→		return idlePhaseStyle.Render("IDLE")
229→	}
230→}
